private static final Instant NOW = Instant.parse("2026-09-05T00:00:00Z");

@Test
void persistsTenThousandDurableEventsInIncrementalRows() throws Exception {
    var database = Files.createTempFile("ji-host-events-", ".db");
    try (HostStore store = store(database)) {
        store.create("session-events", new ModelRef("profile", "model"), "workspace", NOW);
        var config = store.composerConfig("session-events");
        for (int index = 0; index < 10_000; index++) {
            config = store.updateComposerConfig("session-events", config.revision(), config.profileRevision(),
                    config.profileId(), config.modelId(), (index & 1) == 0 ? "a" : "b",
                    config.permissionMode());
        }
        assertEquals(10_000, store.replay("session-events", 0).size());
    }
    try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
        assertEquals(10_000, connection.createStatement()
                .executeQuery("SELECT COUNT(*) FROM ji_host_durable_events").getInt(1));
        assertEquals("[]", connection.createStatement()
                .executeQuery("SELECT CAST(events_json AS TEXT) FROM ji_host_sessions "
                        + "WHERE session_id='session-events'").getString(1));
    }
}

